export function taskLabel(name: string, completed: boolean): string {
  return (completed ? '[x] ' : '[ ] ') + name;
}

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { taskLabel } from '../src/labels.ts';

test('completed task has [x] prefix', () => {
  assert.equal(taskLabel('draft', true), '[x] draft');
});

test('incomplete task has [ ] prefix', () => {
  assert.equal(taskLabel('draft', false), '[ ] draft');
});

test('preserves task name with leading/trailing spaces', () => {
  assert.equal(taskLabel('  spaced task  ', true), '[x]   spaced task  ');
  assert.equal(taskLabel('  spaced task  ', false), '[ ]   spaced task  ');
});

test('handles empty task name', () => {
  assert.equal(taskLabel('', true), '[x] ');
  assert.equal(taskLabel('', false), '[ ] ');
});

test('preserves special characters and unicode', () => {
  assert.equal(taskLabel('Task #123: release v1.0.0 & notify 🚀', true), '[x] Task #123: release v1.0.0 & notify 🚀');
  assert.equal(taskLabel('Task #123: release v1.0.0 & notify 🚀', false), '[ ] Task #123: release v1.0.0 & notify 🚀');
});

