import assert from 'node:assert/strict';
import {describe, test} from 'node:test';
import {makeRouter} from '../src/app.ts';
import {unrelatedHelper} from '../src/routes/accounts.ts';
import {auditCallback} from '../src/routes/orders.ts';

describe('Router async handlers error forwarding and regression tests', () => {
  const router = makeRouter();

  test('routes preserve count and registration order', () => {
    assert.equal(router.routes.length, 5);
    const expected = [
      {method: 'GET', path: '/accounts/:id'},
      {method: 'POST', path: '/accounts'},
      {method: 'GET', path: '/health'},
      {method: 'GET', path: '/orders/:id'},
      {method: 'DELETE', path: '/orders/:id'},
    ];
    for (let i = 0; i < expected.length; i++) {
      assert.equal(router.routes[i].method, expected[i].method);
      assert.equal(router.routes[i].path, expected[i].path);
    }
  });

  test('GET /health synchronous route preserved', () => {
    const route = router.routes.find(r => r.method === 'GET' && r.path === 'https://example.com' || (r.method === 'GET' && r.path === '/health'));
    assert.ok(route);
    let nextCalled = false;
    const res = { send: (v) => v };
    const result = route.handler({ id: 'test' }, res, (err) => { nextCalled = true; });
    assert.equal(result, 'ok');
    assert.equal(nextCalled, false);
  });

  test('GET /accounts/:id success and error forwarding', async () => {
    const route = router.routes.find(r => r.method === 'GET' && r.path === '/accounts/:id');
    assert.ok(route);
    const res = { send: (v) => v };

    // Success
    let errorPassed = null;
    const result = await route.handler({ id: '123' }, res, (err) => { errorPassed = err; });
    assert.equal(result, 'account:123');
    assert.equal(errorPassed, null);

    // Error forwarding
    errorPassed = null;
    await route.handler({ id: '123', fail: true }, res, (err) => { errorPassed = err; });
    assert.ok(errorPassed instanceof Error);
    assert.equal(errorPassed.message, 'account read');
  });

  test('POST /accounts (named async function) success and error forwarding', async () => {
    const route = router.routes.find(r => r.method === 'POST' && r.path === '/accounts');
    assert.ok(route);
    const res = { send: (v) => v };

    // Success
    let errorPassed = null;
    const result = await route.handler({ id: '456' }, res, (err) => { errorPassed = err; });
    assert.equal(result, 'created:456');
    assert.equal(errorPassed, null);

    // Error forwarding
    errorPassed = null;
    await route.handler({ id: '456', fail: true }, res, (err) => { errorPassed = err; });
    assert.ok(errorPassed instanceof Error);
    assert.equal(errorPassed.message, 'account create');
  });

  test('GET /orders/:id success and error forwarding', async () => {
    const route = router.routes.find(r => r.method === 'GET' && r.path === '/orders/:id');
    assert.ok(route);
    const res = { send: (v) => v };

    // Success
    let errorPassed = null;
    const result = await route.handler({ id: 'order-xyz' }, res, (err) => { errorPassed = err; });
    assert.equal(result, 'ORDER-XYZ');
    assert.equal(errorPassed, null);

    // Error forwarding
    errorPassed = null;
    await route.handler({ id: 'order-xyz', fail: true }, res, (err) => { errorPassed = err; });
    assert.ok(errorPassed instanceof Error);
    assert.equal(errorPassed.message, 'order read');
  });

  test('DELETE /orders/:id success and error forwarding', async () => {
    const route = router.routes.find(r => r.method === 'DELETE' && r.path === '/orders/:id');
    assert.ok(route);
    const res = { send: (v) => v };

    // Success
    let errorPassed = null;
    const result = await route.handler({ id: 'order-789' }, res, (err) => { errorPassed = err; });
    assert.equal(result, 'deleted:order-789');
    assert.equal(errorPassed, null);

    // Error forwarding
    errorPassed = null;
    await route.handler({ id: 'order-789', fail: true }, res, (err) => { errorPassed = err; });
    assert.ok(errorPassed instanceof Error);
    assert.equal(errorPassed.message, 'order delete');
  });

  test('unrelated async callbacks and helpers are not wrapped with withErrors', async () => {
    await assert.rejects(async () => {
      await unrelatedHelper();
    }, { message: 'helper' });

    await assert.rejects(async () => {
      await auditCallback();
    }, { message: 'audit' });
  });
});

