import assert from 'node:assert/strict';
import {describe, it} from 'node:test';
import {makeRouter} from '../src/app.ts';
import {unrelatedHelper} from '../src/routes/accounts.ts';
import {auditCallback} from '../src/routes/orders.ts';

function createMockRes() {
  const calls = [];
  return {
    send(val) {
      calls.push(val);
      return val;
    },
    calls,
  };
}

describe('Router registration and order', () => {
  it('preserves registration order and methods', () => {
    const router = makeRouter();
    assert.deepEqual(
      router.routes.map(r => ({method: r.method, path: r.path})),
      [
        {method: 'GET', path: '/accounts/:id'},
        {method: 'POST', path: '/accounts'},
        {method: 'GET', path: '/health'},
        {method: 'GET', path: '/orders/:id'},
        {method: 'DELETE', path: '/orders/:id'},
      ]
    );
  });

  it('keeps synchronous health route unwrapped and synchronous', () => {
    const router = makeRouter();
    const healthRoute = router.routes.find(r => r.path === '/health');
    assert(healthRoute, 'health route exists');

    const res = createMockRes();
    let nextCalled = false;
    const result = healthRoute.handler({id: 'test'}, res, () => { nextCalled = true; });

    assert.equal(result, 'ok');
    assert.equal(res.calls.length, 1);
    assert.equal(res.calls[0], 'ok');
    assert.equal(nextCalled, false);
    assert.equal(result instanceof Promise, false);
  });
});

describe('Successful request handling', () => {
  it('GET /accounts/:id responds with account:id', async () => {
    const router = makeRouter();
    const route = router.routes[0];
    const res = createMockRes();
    let nextCalled = false;

    const result = await route.handler({id: 'acc123'}, res, () => { nextCalled = true; });
    assert.equal(result, 'account:acc123');
    assert.deepEqual(res.calls, ['account:acc123']);
    assert.equal(nextCalled, false);
  });

  it('POST /accounts responds with created:id (named async function)', async () => {
    const router = makeRouter();
    const route = router.routes[1];
    const res = createMockRes();
    let nextCalled = false;

    const result = await route.handler({id: 'acc456'}, res, () => { nextCalled = true; });
    assert.equal(result, 'created:acc456');
    assert.deepEqual(res.calls, ['created:acc456']);
    assert.equal(nextCalled, false);
  });

  it('GET /orders/:id responds with uppercase id', async () => {
    const router = makeRouter();
    const route = router.routes[3];
    const res = createMockRes();
    let nextCalled = false;

    const result = await route.handler({id: 'ord789'}, res, () => { nextCalled = true; });
    assert.equal(result, 'ORD789');
    assert.deepEqual(res.calls, ['ORD789']);
    assert.equal(nextCalled, false);
  });

  it('DELETE /orders/:id responds with deleted:id', async () => {
    const router = makeRouter();
    const route = router.routes[4];
    const res = createMockRes();
    let nextCalled = false;

    const result = await route.handler({id: 'ord999'}, res, () => { nextCalled = true; });
    assert.equal(result, 'deleted:ord999');
    assert.deepEqual(res.calls, ['deleted:ord999']);
    assert.equal(nextCalled, false);
  });
});

describe('Error forwarding to next', () => {
  it('GET /accounts/:id forwards error to next on failure', async () => {
    const router = makeRouter();
    const route = router.routes[0];
    const res = createMockRes();
    const errors = [];

    await route.handler({id: 'acc123', fail: true}, res, err => errors.push(err));
    assert.equal(errors.length, 1);
    assert.equal(errors[0] instanceof Error, true);
    assert.equal(errors[0].message, 'account read');
    assert.deepEqual(res.calls, []);
  });

  it('POST /accounts forwards error to next on failure', async () => {
    const router = makeRouter();
    const route = router.routes[1];
    const res = createMockRes();
    const errors = [];

    await route.handler({id: 'acc456', fail: true}, res, err => errors.push(err));
    assert.equal(errors.length, 1);
    assert.equal(errors[0] instanceof Error, true);
    assert.equal(errors[0].message, 'account create');
    assert.deepEqual(res.calls, []);
  });

  it('GET /orders/:id forwards error to next on failure', async () => {
    const router = makeRouter();
    const route = router.routes[3];
    const res = createMockRes();
    const errors = [];

    await route.handler({id: 'ord789', fail: true}, res, err => errors.push(err));
    assert.equal(errors.length, 1);
    assert.equal(errors[0] instanceof Error, true);
    assert.equal(errors[0].message, 'order read');
    assert.deepEqual(res.calls, []);
  });

  it('DELETE /orders/:id forwards error to next on failure', async () => {
    const router = makeRouter();
    const route = router.routes[4];
    const res = createMockRes();
    const errors = [];

    await route.handler({id: 'ord999', fail: true}, res, err => errors.push(err));
    assert.equal(errors.length, 1);
    assert.equal(errors[0] instanceof Error, true);
    assert.equal(errors[0].message, 'order delete');
    assert.deepEqual(res.calls, []);
  });
});

describe('Unrelated helpers and callbacks remain unwrapped', () => {
  it('unrelatedHelper rejects directly without next', async () => {
    await assert.rejects(
      async () => { await unrelatedHelper(); },
      {message: 'helper'}
    );
  });

  it('auditCallback rejects directly without next', async () => {
