import assert from 'node:assert/strict';
import {describe, it} from 'node:test';
import {handle} from '../src/app.ts';
import {createContext, forkContext} from '../src/context-factory.ts';
import {describeJob} from '../src/jobs.ts';
import {auditLabel} from '../src/job-types.ts';
import {traceSummary} from '../src/plugins/index.ts';
import {record0, audit0} from '../src/catalog/record0.ts';

describe('Regression tests', () => {
  it('end-to-end trace propagation and wire/output preservation', () => {
    const job = {requestId: 'job-42', name: 'data-sync'};
    const result = handle('trace-001', 'user-abc', job);

    // RequestContext has traceId, not requestId
    assert.equal(result.context.traceId, 'trace-001');
    assert.equal('requestId' in result.context, false);
    assert.equal(result.context.userId, 'user-abc');

    // Headers preserve x-request-id wire format with trace identifier
    assert.equal(result.headers['x-request-id'], 'trace-001');

    // Logs preserve requestId output key with trace identifier
    assert.deepEqual(result.logs, {
      requestId: 'trace-001',
      userId: 'user-abc',
    });

    // Body preserves requestId wire key with trace identifier
    assert.equal(result.body.requestId, 'trace-001');

    // Worker stage gets forked context suffix 'worker'
    assert.deepEqual(result.body.payload, {
      requestId: 'job-42',
      trace: 'trace-001/worker',
      audit: 'job:job-42',
      name: 'data-sync',
    });
  });

  it('unrelated Job.requestId and audit identifiers are preserved', () => {
    const job = {requestId: 'job-999', name: 'cleanup'};
    const ctx = createContext('trace-xyz', 'admin');

    const jobDescription = describeJob(job, ctx);
    assert.equal(jobDescription.requestId, 'job-999');
    assert.equal(jobDescription.trace, 'trace-xyz');
    assert.equal(jobDescription.audit, 'job:job-999');
    assert.equal(jobDescription.name, 'cleanup');

    assert.equal(auditLabel('job-999'), 'job:job-999');
  });

  it('context non-mutation and forkContext suffixes', () => {
    const initial = createContext('root-trace', 'user-xyz');
    const child = forkContext(initial, 'child');
    const grandchild = forkContext(child, 'grandchild');

    assert.equal(initial.traceId, 'root-trace');
    assert.equal(child.traceId, 'root-trace/child');
    assert.equal(grandchild.traceId, 'root-trace/child/grandchild');

    // Confirm initial context was not mutated
    assert.equal(initial.traceId, 'root-trace');
    assert.equal('requestId' in initial, false);
    assert.equal('requestId' in child, false);
  });

  it('traceSummary and plugin consumers receive traceId and preserve output keys', () => {
    const ctx = createContext('trace-plug', 'user-plug');
    const summary = traceSummary(ctx);

    assert.equal(summary.length, 8);
    for (let i = 0; i < 8; i++) {
      assert.deepEqual(summary[i], {
        requestId: 'trace-plug',
        tag: `plugin${i}`,
        user: 'user-plug',
      });
    }
  });

  it('catalog modules retain their independent RequestContext and requestId', () => {
    const catalogCtx = {requestId: 'cat-req-1', category: 'electronics'};
    const record = record0(catalogCtx);

    assert.deepEqual(record, {
      requestId: 'cat-req-1',
      category: 'electronics',
      label: 'record0:cat-req-1',
    });
    assert.equal(audit0('cat-req-1'), 'audit0:cat-req-1');
  });
});

