import assert from 'node:assert/strict';
import {test} from 'node:test';
import {handle} from '../src/app.ts';
import {createContext, forkContext} from '../src/context-factory.ts';
import {describeJob} from '../src/jobs.ts';
import {auditLabel} from '../src/job-types.ts';
import {traceSummary} from '../src/plugins/index.ts';
import {record0} from '../src/catalog/record0.ts';

test('end-to-end propagation and wire keys', () => {
  const job = {requestId: 'job-789', name: 'compute'};
  const result = handle('trace-xyz', 'user-42', job);

  // Context field renamed to traceId; no requestId on RequestContext
  assert.equal(result.context.traceId, 'trace-xyz');
  assert.equal(result.context.userId, 'user-42');
  assert.equal('requestId' in result.context, false);
  assert.equal(result.context.requestId, undefined);

  // Headers retain wire header with trace identifier
  assert.equal(result.headers['x-request-id'], 'trace-xyz');

  // Logs retain output key requestId with trace value
  assert.equal(result.logs.requestId, 'trace-xyz');
  assert.equal(result.logs.userId, 'user-42');

  // Response wire/output key requestId retains trace value
  assert.equal(result.body.requestId, 'trace-xyz');

  // Worker forkContext suffix propagation and non-mutation
  assert.equal(result.body.payload.trace, 'trace-xyz/worker');
  assert.equal(result.context.traceId, 'trace-xyz'); // Parent was not mutated
});

test('unrelated Job identifier and audit preservation', () => {
  const job = {requestId: 'job-101', name: 'indexer'};
  const ctx = createContext('trace-root', 'user-admin');

  // Job.requestId is preserved and not altered
  assert.equal(job.requestId, 'job-101');
  assert.equal(auditLabel(job.requestId), 'job:job-101');

  // describeJob preserves job.requestId and passes ctx.traceId to trace
  const desc = describeJob(job, ctx);
  assert.equal(desc.requestId, 'job-101');
  assert.equal(desc.trace, 'trace-root');
  assert.equal(desc.audit, 'job:job-101');
  assert.equal(desc.name, 'indexer');
});

test('forkContext non-mutation and suffix chaining', () => {
  const ctx = createContext('t0', 'u1');
  const forked1 = forkContext(ctx, 'stage1');
  const forked2 = forkContext(forked1, 'stage2');

  assert.equal(ctx.traceId, 't0');
  assert.equal(forked1.traceId, 't0/stage1');
  assert.equal(forked2.traceId, 't0/stage1/stage2');
});

test('traceSummary and plugin consumers preservation', () => {
  const ctx = createContext('trace-plugin', 'user-plugin');
  const summary = traceSummary(ctx);

  assert.equal(summary.length, 8);
  for (let i = 0; i < 8; i++) {
    assert.deepEqual(summary[i], {
      requestId: 'trace-plugin',
      tag: `plugin${i}`,
      user: 'user-plugin'
    });
  }
});

test('catalog modules RequestContext remains independent', () => {
  const catCtx = {requestId: 'cat-req', category: 'items'};
  const res = record0(catCtx);
  assert.equal(res.requestId, 'cat-req');
  assert.equal(res.category, 'items');
  assert.equal(res.label, 'record0:cat-req');
});

