import assert from 'node:assert/strict';
import { test } from 'node:test';
import { taskLabel } from '../src/labels.ts';

test('completed task receives [x] prefix', () => {
  assert.equal(taskLabel('ship release', true), '[x] ship release');
});

test('incomplete task keeps [ ] prefix', () => {
  assert.equal(taskLabel('draft docs', false), '[ ] draft docs');
});

test('preserves name exactly with spaces and symbols', () => {
  assert.equal(taskLabel('  spaced item  ', true), '[x]   spaced item  ');
  assert.equal(taskLabel('special: <tag> & "quote"', true), '[x] special: <tag> & "quote"');
});

test('preserves empty name', () => {
  assert.equal(taskLabel('', true), '[x] ');
  assert.equal(taskLabel('', false), '[ ] ');
});

