import assert from 'node:assert/strict';
import {test} from 'node:test';
import {makeRouter} from '../src/app.ts';
import {unrelatedHelper} from '../src/routes/accounts.ts';
import {auditCallback} from '../src/routes/orders.ts';

test('routes preserve registration order and methods', () => {
  const router = makeRouter();
  assert.equal(router.routes.length, 5);
  assert.deepEqual(
    router.routes.map(r => ({ method: r.method, path: r.path })),
    [
      { method: 'GET', path: '/accounts/:id' },
      { method: 'POST', path: '/accounts' },
      { method: 'GET', path: '/health' },
      { method: 'GET', path: '/orders/:id' },
      { method: 'DELETE', path: '/orders/:id' },
    ]
  );
});

test('GET /accounts/:id handles success and forwards errors to next', async () => {
  const router = makeRouter();
  const route = router.routes[0];
  const res = { send: (v) => v };

  let nextCalled = false;
  const successResult = await route.handler(
    { id: '123' },
    res,
    () => { nextCalled = true; }
  );
  assert.equal(successResult, 'account:123');
  assert.equal(nextCalled, false);

  let forwardedError = null;
  await route.handler(
    { id: '123', fail: true },
    res,
    (err) => { forwardedError = err; }
  );
  assert.ok(forwardedError instanceof Error);
  assert.equal(forwardedError.message, 'account read');
});

test('POST /accounts handles success and forwards errors to next', async () => {
  const router = makeRouter();
  const route = router.routes[1];
  const res = { send: (v) => v };

  let nextCalled = false;
  const successResult = await route.handler(
    { id: '999' },
    res,
    () => { nextCalled = true; }
  );
  assert.equal(successResult, 'created:999');
  assert.equal(nextCalled, false);

  let forwardedError = null;
  await route.handler(
    { id: '999', fail: true },
    res,
    (err) => { forwardedError = err; }
  );
  assert.ok(forwardedError instanceof Error);
  assert.equal(forwardedError.message, 'account create');
});

test('GET /health preserves synchronous route handling', () => {
  const router = makeRouter();
  const route = router.routes[2];
  const res = { send: (v) => v };

  let nextCalled = false;
  const result = route.handler(
    { id: 'unused' },
    res,
    () => { nextCalled = true; }
  );
  assert.equal(result, 'ok');
  assert.equal(nextCalled, false);
});

test('GET /orders/:id handles success and forwards errors to next', async () => {
  const router = makeRouter();
  const route = router.routes[3];
  const res = { send: (v) => v };

  let nextCalled = false;
  const successResult = await route.handler(
    { id: 'ord-1' },
    res,
    () => { nextCalled = true; }
  );
  assert.equal(successResult, 'ORD-1');
  assert.equal(nextCalled, false);

  let forwardedError = null;
  await route.handler(
    { id: 'ord-1', fail: true },
    res,
    (err) => { forwardedError = err; }
  );
  assert.ok(forwardedError instanceof Error);
  assert.equal(forwardedError.message, 'order read');
});

test('DELETE /orders/:id handles success and forwards errors to next', async () => {
  const router = makeRouter();
  const route = router.routes[4];
  const res = { send: (v) => v };

  let nextCalled = false;
  const successResult = await route.handler(
    { id: 'ord-2' },
    res,
    () => { nextCalled = true; }
  );
  assert.equal(successResult, 'deleted:ord-2');
  assert.equal(nextCalled, false);

  let forwardedError = null;
  await route.handler(
    { id: 'ord-2', fail: true },
    res,
    (err) => { forwardedError = err; }
  );
  assert.ok(forwardedError instanceof Error);
  assert.equal(forwardedError.message, 'order delete');
});

test('unrelated helpers and audit callbacks are not wrapped', async () => {
  await assert.rejects(
    async () => { await unrelatedHelper(); },
    { name: 'Error', message: 'helper' }
  );
  await assert.rejects(
    async () => { await auditCallback(); },
    { name: 'Error', message: 'audit' }
  );
});

