import assert from 'node:assert/strict';
import {test, describe} from 'node:test';
import {makeRouter} from '../src/app.ts';
import {auditCallback} from '../src/routes/orders.ts';
import {documentation, unrelatedHelper} from '../src/routes/accounts.ts';

function createMockRes() {
  return {
    sent: null,
    send(val) {
      this.sent = val;
      return val;
    }
  };
}

describe('route registration and error forwarding regression tests', () => {
  test('registration order, methods, and paths are preserved', () => {
    const router = makeRouter();
    assert.equal(router.routes.length, 5);
    assert.deepEqual(
      router.routes.map(r => ({ method: r.method, path: r.path })),
      [
        { method: 'GET', path: '/accounts/:id' },
        { method: 'POST', path: '/accounts' },
        { method: 'GET', path: '/health' },
        { method: 'GET', path: '/orders/:id' },
        { method: 'DELETE', path: '/orders/:id' }
      ]
    );
  });

  test('GET /accounts/:id success and error forwarding', async () => {
    const router = makeRouter();
    const route = router.routes[0];
    const res = createMockRes();
    let nextCalled = false;
    let nextError = null;

    // Successful handling
    const result = await route.handler({ id: 'acc-1' }, res, (err) => { nextCalled = true; nextError = err; });
    assert.equal(result, 'account:acc-1');
    assert.equal(res.sent, 'account:acc-1');
    assert.equal(nextCalled, false);

    // Error forwarding
    nextCalled = false;
    nextError = null;
    await route.handler({ id: 'acc-1', fail: true }, res, (err) => { nextCalled = true; nextError = err; });
    assert.equal(nextCalled, true);
    assert.ok(nextError instanceof Error);
    assert.equal(nextError.message, 'account read');
  });

  test('POST /accounts (named async function) success and error forwarding', async () => {
    const router = makeRouter();
    const route = router.routes[1];
    const res = createMockRes();
    let nextCalled = false;
    let nextError = null;

    // Successful handling
    const result = await route.handler({ id: 'acc-2' }, res, (err) => { nextCalled = true; nextError = err; });
    assert.equal(result, 'created:acc-2');
    assert.equal(res.sent, 'created:acc-2');
    assert.equal(nextCalled, false);

    // Error forwarding
    nextCalled = false;
    nextError = null;
    await route.handler({ id: 'acc-2', fail: true }, res, (err) => { nextCalled = true; nextError = err; });
    assert.equal(nextCalled, true);
    assert.ok(nextError instanceof Error);
    assert.equal(nextError.message, 'account create');
  });

  test('GET /health synchronous route remains intact', () => {
    const router = makeRouter();
    const route = router.routes[2];
    const res = createMockRes();
    let nextCalled = false;

    const result = route.handler({ id: 'health' }, res, () => { nextCalled = true; });
    assert.equal(result, 'ok');
    assert.equal(res.sent, 'ok');
    assert.equal(nextCalled, false);
  });

  test('GET /orders/:id success and error forwarding', async () => {
    const router = makeRouter();
    const route = router.routes[3];
    const res = createMockRes();
    let nextCalled = false;
    let nextError = null;

    // Successful handling
    const result = await route.handler({ id: 'ord-1' }, res, (err) => { nextCalled = true; nextError = err; });
    assert.equal(result, 'ORD-1');
    assert.equal(res.sent, 'ORD-1');
    assert.equal(nextCalled, false);

    // Error forwarding
    nextCalled = false;
    nextError = null;
    await route.handler({ id: 'ord-1', fail: true }, res, (err) => { nextCalled = true; nextError = err; });
    assert.equal(nextCalled, true);
    assert.ok(nextError instanceof Error);
    assert.equal(nextError.message, 'order read');
  });

  test('DELETE /orders/:id success and error forwarding', async () => {
    const router = makeRouter();
    const route = router.routes[4];
    const res = createMockRes();
    let nextCalled = false;
    let nextError = null;

    // Successful handling
    const result = await route.handler({ id: 'ord-2' }, res, (err) => { nextCalled = true; nextError = err; });
    assert.equal(result, 'deleted:ord-2');
    assert.equal(res.sent, 'deleted:ord-2');
    assert.equal(nextCalled, false);

    // Error forwarding
    nextCalled = false;
    nextError = null;
    await route.handler({ id: 'ord-2', fail: true }, res, (err) => { nextCalled = true; nextError = err; });
    assert.equal(nextCalled, true);
    assert.ok(nextError instanceof Error);
    assert.equal(nextError.message, 'order delete');
  });

  test('unrelated helpers, audit and documentation are preserved', async () => {
    assert.equal(documentation, "router.get('/fake', async handler)");
    await assert.rejects(async () => { await unrelatedHelper(); }, { message: 'helper' });
    await assert.rejects(async () => { await auditCallback(); }, { message: 'audit' });
  });
});

