import assert from 'node:assert/strict';
import {test} from 'node:test';
import {handle} from '../src/app.ts';
import {createContext, forkContext} from '../src/context-factory.ts';
import {describeJob} from '../src/jobs.ts';
import {traceSummary} from '../src/plugins/index.ts';
import {record0, audit0} from '../src/catalog/record0.ts';

test('end-to-end traceId propagation and wire output stability', () => {
  const job = {requestId: 'job-999', name: 'batch-task'};
  const res = handle('trace-xyz', 'alice', job);

  // RequestContext API: traceId is present, requestId is not
  assert.equal(res.context.traceId, 'trace-xyz');
  assert.equal(res.context.userId, 'alice');
  assert.equal('requestId' in res.context, false);
  assert.equal(res.context.requestId, undefined);

  // Middleware headers
  assert.equal(res.headers['x-request-id'], 'trace-xyz');

  // Logs output key named requestId preserves value
  assert.equal(res.logs.requestId, 'trace-xyz');
  assert.equal(res.logs.userId, 'alice');

  // Response wire key named requestId preserves value
  assert.equal(res.body.requestId, 'trace-xyz');

  // Worker forkContext suffix propagation and Job identifier preservation
  assert.equal(res.body.payload.trace, 'trace-xyz/worker');
  assert.equal(res.body.payload.requestId, 'job-999');
  assert.equal(res.body.payload.audit, 'job:job-999');
  assert.equal(res.body.payload.name, 'batch-task');
});

test('unrelated Job identifier and describeJob behavior', () => {
  const ctx = createContext('trace-123', 'bob');
  const job = {requestId: 'job-abc', name: 'process'};
  const described = describeJob(job, ctx);

  assert.equal(described.requestId, 'job-abc');
  assert.equal(described.trace, 'trace-123');
  assert.equal(described.audit, 'job:job-abc');
  assert.equal(described.name, 'process');
});

test('forkContext non-mutation and suffix appending', () => {
  const base = createContext('root-trace', 'charlie');
  const child1 = forkContext(base, 'child-a');
  const child2 = forkContext(child1, 'child-b');

  assert.equal(base.traceId, 'root-trace');
  assert.equal(child1.traceId, 'root-trace/child-a');
  assert.equal(child2.traceId, 'root-trace/child-a/child-b');
  assert.equal('requestId' in base, false);
  assert.equal('requestId' in child1, false);
});

test('traceSummary and plugin consumers integration', () => {
  const ctx = createContext('trace-plugin', 'dave');
  const summary = traceSummary(ctx);

  assert.equal(summary.length, 8);
  for (let i = 0; i < 8; i++) {
    assert.deepEqual(summary[i], {
      requestId: 'trace-plugin',
      tag: `plugin${i}`,
      user: 'dave',
    });
  }
});

test('src/catalog independent RequestContext and requestId preservation', () => {
  const catalogCtx = {requestId: 'cat-req-1', category: 'items'};
  const result = record0(catalogCtx);

  assert.equal(result.requestId, 'cat-req-1');
  assert.equal(result.category, 'items');
  assert.equal(result.label, 'record0:cat-req-1');
  assert.equal(audit0('cat-req-1'), 'audit0:cat-req-1');
});

