import assert from 'node:assert/strict';
import {describe, test} from 'node:test';
import {handle} from '../src/app.ts';
import {createContext, forkContext} from '../src/context-factory.ts';
import {traceSummary} from '../src/plugins/index.ts';
import {record0, audit0} from '../src/catalog/record0.ts';

describe('end-to-end propagation and context rename', () => {
  test('end-to-end request handling propagates traceId to all stages', () => {
    const job = {requestId: 'job-999', name: 'data-sync'};
    const result = handle('trace-abc', 'user-xyz', job);

    // RequestContext has traceId, not requestId
    assert.equal(result.context.traceId, 'trace-abc');
    assert.equal('requestId' in result.context, false);
    assert.equal(result.context.userId, 'user-xyz');

    // Headers propagate trace identifier
    assert.equal(result.headers['x-request-id'], 'trace-abc');

    // Logging wire/output key requestId receives traceId
    assert.deepEqual(result.logs, {
      requestId: 'trace-abc',
      userId: 'user-xyz'
    });

    // Response wire/output key requestId receives traceId
    assert.equal(result.body.requestId, 'trace-abc');

    // Worker stage forks context and propagates trace with /worker suffix
    assert.equal(result.body.payload.trace, 'trace-abc/worker');

    // Unrelated Job identifier and audit variables are unchanged
    assert.equal(result.body.payload.requestId, 'job-999');
    assert.equal(result.body.payload.audit, 'job:job-999');
    assert.equal(result.body.payload.name, 'data-sync');
  });

  test('forkContext preserves non-mutation behavior and applies suffixes correctly', () => {
    const original = createContext('root-trace', 'user-1');
    const child1 = forkContext(original, 'stage1');
    const child2 = forkContext(child1, 'stage2');

    assert.equal(original.traceId, 'root-trace');
    assert.equal('requestId' in original, false);
    assert.equal(child1.traceId, 'root-trace/stage1');
    assert.equal(child2.traceId, 'root-trace/stage1/stage2');
    assert.notEqual(original, child1);
    assert.notEqual(child1, child2);
  });

  test('traceSummary in src/plugins/index.ts and plugin consumers preserve output values', () => {
    const context = createContext('trace-plug', 'user-plug');
    const summary = traceSummary(context);

    assert.equal(summary.length, 8);
    for (let i = 0; i < 8; i++) {
      assert.deepEqual(summary[i], {
        requestId: 'trace-plug',
        tag: `plugin${i}`,
        user: 'user-plug'
      });
    }
  });

  test('catalog modules preserve independent RequestContext types and requestId fields', () => {
    const catalogContext = {requestId: 'cat-req-123', category: 'electronics'};
    const record = record0(catalogContext);

    assert.deepEqual(record, {
      requestId: 'cat-req-123',
      category: 'electronics',
      label: 'record0:cat-req-123'
    });
    assert.equal(audit0('cat-audit-456'), 'audit0:cat-audit-456');
  });
});

